{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Thus, the objective of this review was to systematically describe the decision-making process of rural parents regarding their use of antibiotics. We sought to address the following research question: What factors influence the decisions of parents with children living in rural and remote locations in their use of antibiotics?",
      "reason": "The review provides an explicit objective and states a specific research question the review addresses."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "However, the purpose of the review was to describe, rather than quantify, a process of decision-making.",
      "reason": "The retrieved evidence indicates the review aims to describe a decision-making process rather than evaluate intervention effects with planned comparative analyses; therefore PICO-style planned comparisons are not applicable for this objective."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Worldwide studies available in English were included, and no restrictions were placed on the publication period. Both peerreviewed and grey literature were accepted. Studies were eligible if they provided data on the decision-making process of parents living in rural and remote locations in their use of antibiotics with their children (aged 0-18 years). This included an examination of all factors influencing parent decisions to use antibiotics, and factors contributing to how antibiotics were acquired and used. We considered quantitative and qualitative designs, mixed methods, observational, prospective, systematic reviews, crosssectional and longitudinal studies.",
      "reason": "Inclusion criteria clearly specify relevant study characteristics (population: rural/remote parents; intervention/exposure: parental decision-making about children’s antibiotic use; age range; and eligible study designs/settings). However, the evidence provided does not explicitly describe “follow-up requirements.”"
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Worldwide studies available in English were included, and no restrictions were placed on the publication period. Both peerreviewed and grey literature were accepted.",
      "reason": "Report characteristics eligibility is specified for language (English), publication period (no restrictions), and publication/report status (peer-reviewed and grey literature)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "null",
      "quote": null,
      "reason": "The provided evidence lists exclusion reasons (e.g., unsuitable participant characteristics; lack of exclusive results; lack of data on decision-making process), but does not distinguish exclusion based on outcomes “not measured” versus “not reported.”"
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "Primary findings were categorised into groups for the synthesis: (1) the process of decision-making to use or not use antibiotics i.e., influences on antibiotic use (2) factors contributing to specific behaviours with antibiotics identified i.e., non-prescription use of antibiotics, non-adherence to antibiotic treatment, requests for antibiotic prescriptions.",
      "reason": "The review specifies how findings were grouped for synthesis (the two categories and the sub-areas listed). However, the evidence does not explicitly show how these groups are linked to the specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "null",
      "quote": null,
      "reason": "Although eligibility restrictions are described (e.g., limited to studies available in English), the retrieved evidence does not provide rationales for notable restrictions on study eligibility."
    }
  ],
  "confidence": 68
}

